function ShimmerButton({ children }) {
  return (
    <button className="group relative px-8 py-4 bg-gradient-to-r from-purple-600 to-pink-600 text-white font-semibold rounded-xl overflow-hidden transition-all hover:scale-105 hover:shadow-xl hover:shadow-purple-500/25">
      {/* Shimmer effect */}
      <div className="absolute inset-0 -translate-x-full group-hover:translate-x-full transition-transform duration-1000 bg-gradient-to-r from-transparent via-white/20 to-transparent" />
      <span className="relative z-10">{children || 'Get Started'}</span>
    </button>
  );
}

function GlowButton({ children }) {
  return (
    <button className="relative px-8 py-4 bg-black text-white font-semibold rounded-xl group">
      {/* Glow effect */}
      <div className="absolute -inset-1 bg-gradient-to-r from-purple-600 to-pink-600 rounded-xl blur opacity-25 group-hover:opacity-75 transition duration-200" />
      <div className="relative bg-black px-8 py-4 rounded-xl">
        {children || 'Explore Now'}
      </div>
    </button>
  );
}

function GradientBorderButton({ children }) {
  return (
    <button className="relative p-[2px] rounded-xl bg-gradient-to-r from-purple-500 via-pink-500 to-red-500 group">
      <div className="bg-white group-hover:bg-gray-50 px-8 py-3 rounded-[10px] transition-colors">
        <span className="bg-gradient-to-r from-purple-500 via-pink-500 to-red-500 bg-clip-text text-transparent font-semibold">
          {children || 'Learn More'}
        </span>
      </div>
    </button>
  );
}

function Button3D({ children }) {
