    <button className="px-8 py-4 bg-blue-500 text-white font-bold rounded-xl shadow-[0_6px_0_0_#2563eb] hover:shadow-[0_4px_0_0_#2563eb] hover:translate-y-[2px] active:shadow-none active:translate-y-[6px] transition-all">
      {children || 'Click Me'}
    </button>
  );
}
